import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.CHxxV8OH.js";const h=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1775890242000}'),i={name:"roadmap.md"};function n(s,t,l,d,g,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Agent Studio is actively developed. Here&#39;s what&#39;s planned for upcoming releases.</p><h2 id="current-release" tabindex="-1">Current Release <a class="header-anchor" href="#current-release" aria-label="Permalink to &quot;Current Release&quot;">​</a></h2><p><strong>Agent Studio 1.0.0</strong> (Latest Stable)</p><ul><li>Visual agent builder with rich editor</li><li>Handoff graph visualization</li><li>Capabilities inspector (Tools, Skills, MCP servers)</li><li>Workflow orchestration (sequential)</li><li>Local-first architecture with version control</li><li>Dark mode with responsive design</li></ul><h2 id="q2-2026" tabindex="-1">Q2 2026 <a class="header-anchor" href="#q2-2026" aria-label="Permalink to &quot;Q2 2026&quot;">​</a></h2><p><strong>Planned Features:</strong></p><ul><li><strong>Workflow Templates</strong>: Pre-built workflow patterns for common scenarios (approval chains, escalation flows, multi-step data pipelines)</li><li><strong>Advanced Search</strong>: Full-text search across agent instructions, capabilities, and relationships</li><li><strong>Import/Export</strong>: Bulk import agents from JSON/YAML; export workflows as shareable templates</li><li><strong>Settings Sync</strong>: Sync Agent Studio preferences and workspace configuration via VS Code Settings Sync</li><li><strong>Performance Optimization</strong>: Graph rendering improvements for 200+ agent workspaces</li></ul><p><strong>Fixes &amp; Polish:</strong></p><ul><li>Keyboard navigation improvements throughout dashboard</li><li>Better error messages for capability mismatches</li><li>Improved MCP server auto-discovery and docs</li></ul><h2 id="q3-2026" tabindex="-1">Q3 2026 <a class="header-anchor" href="#q3-2026" aria-label="Permalink to &quot;Q3 2026&quot;">​</a></h2><p><strong>Planned Features:</strong></p><ul><li><strong>Conditional Workflows</strong>: Branch logic in workflows based on agent outputs</li><li><strong>Agent Testing</strong>: Built-in test runner for individual agents and workflows</li><li><strong>Documentation Generator</strong>: Auto-generate docs for your agents and workflows in Markdown</li><li><strong>Analytics Dashboard</strong>: Track agent usage, performance metrics, and error rates</li><li><strong>Team Presence</strong>: Real-time collaboration indicators (see which team members are editing which agents)</li></ul><p><strong>Community Contributions:</strong></p><ul><li>First community-submitted extensions and plugins</li><li>Expanded MCP server integrations</li></ul><h2 id="q4-2026" tabindex="-1">Q4 2026 <a class="header-anchor" href="#q4-2026" aria-label="Permalink to &quot;Q4 2026&quot;">​</a></h2><p><strong>Planned Features:</strong></p><ul><li><strong>Scheduled Workflows</strong>: Cron-based execution for recurring agent tasks</li><li><strong>Webhook Triggers</strong>: External systems can trigger workflows via HTTP</li><li><strong>Agent Versioning</strong>: Tag and rollback agent definitions across time</li><li><strong>Advanced Authorization</strong>: Fine-grained permission control (which team members can edit which agents)</li><li><strong>Multi-Workspace Support</strong>: Manage agents across multiple VS Code workspace folders</li><li><strong>Cloud Sync (Optional)</strong>: Teams can optionally sync agent definitions to a shared service (fully backward-compatible; local-first by default)</li></ul><h2 id="backlog-future" tabindex="-1">Backlog (Future) <a class="header-anchor" href="#backlog-future" aria-label="Permalink to &quot;Backlog (Future)&quot;">​</a></h2><p><strong>Longer-term roadmap:</strong></p><ul><li><strong>Agent Marketplace</strong>: Share agents, skills, and workflows with other developers</li><li><strong>Custom UI Components</strong>: Build custom dashboards and visualizations within Agent Studio</li><li><strong>Agent Profiling</strong>: Bottleneck analysis and performance optimization suggestions</li><li><strong>Deployment Integration</strong>: Direct deployment of agents to cloud platforms (Azure Container Instances, AWS Lambda, etc.)</li><li><strong>Mobile Dashboard</strong>: Read-only mobile companion for monitoring workflows</li><li><strong>Voice Commands</strong>: Use VS Code voice commands to trigger agent actions</li><li><strong>WASM Extensions</strong>: Extend Agent Studio capabilities via WebAssembly plugins</li></ul><h2 id="how-to-contribute" tabindex="-1">How to Contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to &quot;How to Contribute&quot;">​</a></h2><p>Have an idea or want to help? Here&#39;s how:</p><ol><li><strong>Report Issues</strong>: Found a bug? <a href="https://github.com/eric44/agent-studio/issues" target="_blank" rel="noreferrer">Open an issue</a></li><li><strong>Request Features</strong>: Want a capability on the roadmap sooner? <a href="https://github.com/eric44/agent-studio/discussions" target="_blank" rel="noreferrer">Submit a feature request</a></li><li><strong>Submit PRs</strong>: Check the <a href="https://github.com/eric44/agent-studio/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">contributing guide</a> for development setup</li><li><strong>Share Feedback</strong>: Join the <a href="https://github.com/eric44/agent-studio/discussions" target="_blank" rel="noreferrer">discussions forum</a> and share how you&#39;re using Agent Studio</li></ol><h2 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Release Date</th><th>Highlights</th></tr></thead><tbody><tr><td>1.0.0</td><td>Apr 11 2026</td><td>Initial public release; visual agent builder, graphs, capabilities inspector</td></tr><tr><td>0.9.0</td><td>Apr 2026</td><td>Beta; core features, community feedback incorporation</td></tr><tr><td>0.1.0</td><td>Apr 2026</td><td>Alpha/internal; foundation and architecture</td></tr></tbody></table><hr><p><strong><a href="/agent-studio/features">← Features</a></strong> | <strong><a href="https://github.com/eric44/agent-studio/issues" target="_blank" rel="noreferrer">Report a Bug →</a></strong></p>',28)])])}const p=e(i,[["render",n]]);export{h as __pageData,p as default};
